
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_r2scanh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_r2scanh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.422586449915940e+00, -4.333540287112273e+00, -4.208724049065729e+00, -4.035735035830530e+00, -3.799827385226423e+00, -3.485444116708059e+00, -3.079911319166089e+00, -2.580101904407578e+00, -2.001233166454735e+00, -1.377229696424620e+00, -7.956311613782748e-01, -6.029192705064111e-01, -6.049401646716281e-01, -5.025924109423855e-01, -3.453320508687096e-01, -1.918275501867156e-01, -7.816198961577013e-02, -2.162028340927508e-02, -3.143425248412799e-03, -1.515727659550415e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


